import{_ as t,o as a,c as n,a2 as i}from"./chunks/framework.CIO_ahoo.js";const p=JSON.parse('{"title":"Pending payments","description":"What settlement_pending means, why it is not a failure, and what the merchant, the payer and a direct facilitator caller should each do with it.","frontmatter":{"description":"What settlement_pending means, why it is not a failure, and what the merchant, the payer and a direct facilitator caller should each do with it."},"headers":[],"relativePath":"guides/pending-payments.md","filePath":"guides/pending-payments.md"}'),o={name:"guides/pending-payments.md"};function r(s,e,d,c,l,h){return a(),n("div",null,[...e[0]||(e[0]=[i('<h1 id="pending-payments" tabindex="-1">Pending payments <a class="header-anchor" href="#pending-payments" aria-label="Permalink to &quot;Pending payments&quot;">​</a></h1><p><code>settlement_pending</code> means the facilitator relayed the payer-signed transaction to Canton but does not know yet whether it committed: the participant took it, and then the answer was lost or slow. <strong>It is not a failure.</strong> The transaction may still commit, and if it does the payer has paid. Treating it as a failure is how a payer ends up paying twice.</p><h2 id="what-a-retry-tells-you" tabindex="-1">What a retry tells you <a class="header-anchor" href="#what-a-retry-tells-you" aria-label="Permalink to &quot;What a retry tells you&quot;">​</a></h2><p>The facilitator remembers every transaction it relayed. Presenting the same payment again, at verify or at settle, does not submit it again; it answers with what the facilitator knows:</p><table tabindex="0"><thead><tr><th>The first relay…</th><th>A retry of the same payment answers</th></tr></thead><tbody><tr><td>is still unresolved</td><td><code>settlement_pending</code></td></tr><tr><td>committed</td><td><code>settlement_pending</code></td></tr><tr><td>was rejected by the ledger</td><td><code>invalid_exact_canton_execute_failed</code></td></tr></tbody></table><p>A retry can tell you a payment <strong>failed</strong>, so the payer can sign a new one. It cannot tell you it succeeded: the spec forbids a facilitator from answering a settle from a remembered commit, so a committed payment keeps answering <code>settlement_pending</code>. Once the transfer&#39;s deadline has passed, a retry is refused as <code>invalid_exact_canton_expired</code> before any of this.</p><p>The answer names the transaction, in <code>transaction</code> on settle and in <code>extra.transaction</code> on verify. It is the payment&#39;s <code>preparedTxHash</code>, since there is no update id until it commits.</p><h2 id="merchants" tabindex="-1">Merchants <a class="header-anchor" href="#merchants" aria-label="Permalink to &quot;Merchants&quot;">​</a></h2><p>The Express middleware answers a pending settlement with a <code>402</code> carrying only <code>PAYMENT-RESPONSE</code>: no new challenge, so a client is not invited to pay again. The request is not served, and <code>onReject</code> is not called, since nothing is owed an undo.</p><p>The funds may still land at your party. If they do, serve or refund the order out of band, matching it by the transaction hash or your <code>memo</code>.</p><h2 id="payers" tabindex="-1">Payers <a class="header-anchor" href="#payers" aria-label="Permalink to &quot;Payers&quot;">​</a></h2><ul><li><strong>Do not sign a new payment</strong> for a request answered <code>settlement_pending</code>. The first one may still move your funds.</li><li><strong>Do not retry the request through <code>createX402Fetch</code>.</strong> The wrapper sends one payment and returns what comes back; called again, it gets a fresh <code>402</code> and signs a second transfer.</li><li><strong>Check it with <code>isSettlementPending</code></strong> from <code>@chainsafe/x402-core</code>, on the settle answer decoded from <code>PAYMENT-RESPONSE</code> (<code>decodePaymentResponseHeader</code>).</li><li>Re-sending the <strong>same</strong> <code>PAYMENT-SIGNATURE</code> header is safe, and tells you if the payment failed. If it keeps answering <code>settlement_pending</code>, take it up with the merchant, naming the transaction.</li></ul><h2 id="calling-the-facilitator-directly" tabindex="-1">Calling the facilitator directly <a class="header-anchor" href="#calling-the-facilitator-directly" aria-label="Permalink to &quot;Calling the facilitator directly&quot;">​</a></h2><p><code>FacilitatorClient.settle</code> returns a pending answer as a value, not an error, since the facilitator sends it with HTTP <code>200</code>. Settling the same payload again is safe: it never submits twice, and it answers <code>invalid_exact_canton_execute_failed</code> if the first relay was rejected. A payment that keeps answering <code>settlement_pending</code> has to be confirmed on the ledger, by its transaction.</p>',14)])])}const y=t(o,[["render",r]]);export{p as __pageData,y as default};
